import{_ as n,o as t,c as o,a0 as s}from"./chunks/framework.Cp0xpwNH.js";const g=JSON.parse('{"title":"A1 Level: Beginner","description":"","frontmatter":{},"headers":[],"relativePath":"A1/index.md","filePath":"A1/index.md"}'),r={name:"A1/index.md"};function a(i,e,l,c,d,u){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="a1-level-beginner" tabindex="-1">A1 Level: Beginner <a class="header-anchor" href="#a1-level-beginner" aria-label="Permalink to &quot;A1 Level: Beginner&quot;">​</a></h1><p><strong>CEFR Level:</strong> A1 (Beginner)</p><p><strong>Total Lessons:</strong> 11 content lessons + 1 review lesson</p><p>Welcome to the A1 (Beginner) level of the Dutch B1 Curriculum. At this level, you&#39;ll build on the foundations from A0 and develop the ability to construct simple sentences, ask and answer basic questions, describe daily routines, and express simple opinions and preferences.</p><hr><h2 id="learning-outcomes" tabindex="-1">Learning Outcomes <a class="header-anchor" href="#learning-outcomes" aria-label="Permalink to &quot;Learning Outcomes&quot;">​</a></h2><p>By the end of A1, you will be able to:</p><ul><li><strong>Construct simple sentences</strong> with correct subject-verb agreement and word order</li><li><strong>Ask and answer yes/no and question-word questions</strong> in present tense</li><li><strong>Describe daily routines</strong> using regular verbs and adverbs of frequency</li><li><strong>Talk about food, shopping, locations, clothing, and professions</strong> using basic vocabulary and simple sentences</li><li><strong>Express simple opinions and preferences</strong> using basic adjectives and modal verbs</li><li><strong>Use basic past tense</strong> to talk about recent activities</li><li><strong>Navigate simple social interactions</strong> with increasing confidence and appropriate register</li></ul><hr><h2 id="competencies" tabindex="-1">Competencies <a class="header-anchor" href="#competencies" aria-label="Permalink to &quot;Competencies&quot;">​</a></h2><h3 id="competency-1-basic-sentences-and-word-order" tabindex="-1">Competency 1: Basic Sentences and Word Order <a class="header-anchor" href="#competency-1-basic-sentences-and-word-order" aria-label="Permalink to &quot;Competency 1: Basic Sentences and Word Order&quot;">​</a></h3><p>Master present-tense verb conjugation, SVO word order, the V2 (verb-second) rule, question formation through verb inversion, question-word questions, and negation with &quot;niet&quot; and &quot;geen.&quot;</p><ul><li><strong>Lesson A1-01:</strong> Basic Sentences and Word Order</li></ul><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>Begin with <strong>Lesson A1-01: Basic Sentences and Word Order</strong> to build your foundation in present-tense sentence construction and basic questioning.</p><p>After completing A1, you&#39;ll move to the <strong>A2 (Elementary)</strong> level, where you&#39;ll explore more complex past tenses, conditional statements, and expanded vocabulary for real-world contexts like housing, healthcare, and travel.</p>',17)])])}const h=n(r,[["render",a]]);export{g as __pageData,h as default};
